CREATE TABLE IF NOT EXISTS p2_schema(version INTEGER PRIMARY KEY,applied REAL NOT NULL);
CREATE TABLE IF NOT EXISTS p2_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,mission_id TEXT NOT NULL REFERENCES mm_missions(id),event_key TEXT NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL,created REAL NOT NULL,UNIQUE(mission_id,event_key));
CREATE TABLE IF NOT EXISTS p2_outbox(mission_id TEXT PRIMARY KEY REFERENCES mm_missions(id),creator TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL,upstream_id TEXT,attempts INTEGER NOT NULL DEFAULT 0,lease_until REAL NOT NULL DEFAULT 0,created REAL NOT NULL,updated REAL NOT NULL);
CREATE TABLE IF NOT EXISTS p2_approvals(id TEXT PRIMARY KEY,mission_id TEXT NOT NULL REFERENCES mm_missions(id),requester TEXT NOT NULL,action TEXT NOT NULL,fingerprint TEXT NOT NULL,state TEXT NOT NULL,expires REAL NOT NULL,decider TEXT,created REAL NOT NULL,UNIQUE(mission_id,fingerprint));
CREATE TABLE IF NOT EXISTS p2_llm_jobs(id TEXT PRIMARY KEY,owner TEXT NOT NULL,scope TEXT NOT NULL,event_key TEXT NOT NULL,fingerprint TEXT NOT NULL,input TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL,max_tokens INTEGER NOT NULL,reserved_tokens INTEGER NOT NULL DEFAULT 0,used_tokens INTEGER NOT NULL DEFAULT 0,deadline REAL NOT NULL,lease_until REAL NOT NULL DEFAULT 0,result TEXT,metrics TEXT NOT NULL DEFAULT '[]',UNIQUE(owner,scope,event_key));
CREATE TABLE IF NOT EXISTS p2_skills(owner TEXT NOT NULL,scope TEXT NOT NULL,name TEXT NOT NULL,version INTEGER NOT NULL,spec TEXT NOT NULL,fingerprint TEXT NOT NULL,sources TEXT NOT NULL,state TEXT NOT NULL,evaluation TEXT,proposed_by TEXT NOT NULL,published_by TEXT,PRIMARY KEY(owner,scope,name,version));
CREATE TABLE IF NOT EXISTS p2_skill_active(owner TEXT NOT NULL,scope TEXT NOT NULL,name TEXT NOT NULL,version INTEGER NOT NULL,PRIMARY KEY(owner,scope,name));
CREATE TABLE IF NOT EXISTS p2_skill_audit(seq INTEGER PRIMARY KEY AUTOINCREMENT,owner TEXT NOT NULL,scope TEXT NOT NULL,name TEXT NOT NULL,version INTEGER NOT NULL,action TEXT NOT NULL,actor TEXT NOT NULL,created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS p2_budgets(id TEXT PRIMARY KEY,owner TEXT NOT NULL,monthly_remote_micros INTEGER NOT NULL,token_limit INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS p2_usage(id TEXT PRIMARY KEY,budget_id TEXT NOT NULL REFERENCES p2_budgets(id),month TEXT NOT NULL,mission_id TEXT NOT NULL,parent_call TEXT,model TEXT NOT NULL,reserved_tokens INTEGER NOT NULL,used_tokens INTEGER,reserved_remote_micros INTEGER NOT NULL,actual_remote_micros INTEGER,latency REAL,state TEXT NOT NULL,created REAL NOT NULL);
